'use strict';
const {test}=require('node:test'),assert=require('node:assert/strict');
const Preview=require('../architecture/strategy-preview-bridge.cjs');
const Comparison=require('../architecture/strategy-comparison-contract.cjs');
const Risk=require('../position-risk.js');
const Core=require('../financial-engine.js');
const Rules=require('../kraken-rules.js');
const fx=require('./helpers/cycle-fixture.cjs');
const rulebook=require('../rules/kraken/eea-pf-xbtusd-20261021.json');
const when={asOf:'2026-10-20T23:40:00Z',platform:'europa',clientType:'retail'};
const today={...when,asOf:'2026-10-25T14:05:00Z'};
const input=mode=>({schemaVersion:1,mode,profile:'balanced',referencePriceUSD:'80000',firstEntryPriceUSD:'80000',riskFloorUSD:'60000',buyLadderLowerBoundUSD:'60000',cycleFirstEntryGapUSD:mode==='v20-base-illustrative'?'240':'1000',withinCycleReinforcementGapUSD:mode==='v20-base-illustrative'?'1200':'8000',maxCycles:5,nominalCycleBudgetUSD:'1000',walletCashUSD:'2000',reportedIsolatedMarginUSD:'100',plannedMarginAddsUSD:'300',protectedCashUSD:'400'});
const run=(mode,asOf=when,engine=Risk)=>Preview.run({request:input(mode),rules:rulebook,context:asOf,riskEngine:engine});
const seed=()=>{const s=fx.input();s.events.push(fx.event(2,'margin_add',{amountUSD:'100',currency:'USD',purpose:'initial'}),fx.event(3,'trade_buy',{symbol:'PF_XBTUSD',executionStatus:'executed',quantityBTC:'0.01',priceUSD:'100000',cycle:'cycle-1'}));return s;};
test('R3.4 real risk engine receives the quantized V20 base ladder, never the raw notional',()=>{const x=run('v20-base-illustrative');assert.equal(x.orders.length,15);assert.equal(x.risk.status,'v20-estimate-under-synthetic-all-fills');assert.equal(x.risk.officialLiquidation,false);assert.equal(x.canApply,false);assert.equal(x.mayCallExchange,false);assert.equal(x.risk.result.initialRequiredUSD,'496.527');assert.ok(Number(x.risk.result.requiredTotalMarginUSD)>Number(x.risk.result.initialRequiredUSD));});
test('classic A-E remains blocked at risk floor, even with a real engine attached',()=>{const x=run('classic-demo');assert.equal(x.ladder.levels.at(-1).entryPriceUSD,'60000');assert.equal(x.risk.status,'blocked');assert.equal(x.risk.reason,'INVALID_PRICE_OR_LOT_LADDER');assert.ok(x.orders.at(-1).issues.includes('AT_OR_BELOW_RISK_FLOOR'));});
test('stale Kraken rulebook blocks the engine call without rewriting observedAt',()=>{const x=run('v20-base-illustrative',today,{requiredMarginForFloor:()=>{throw Error('should never be called');}});assert.equal(x.ruleAssessment.scopeReady,false);assert.equal(x.risk.status,'blocked');assert.equal(x.risk.reason,'STALE_OR_OUT_OF_SCOPE_KRAKEN_RULES');assert.equal(x.sourceRulesObservedAt,rulebook.observedAt);});
test('exact source rules remain unchanged',()=>{const snapshot=JSON.stringify(rulebook);run('v20-base-illustrative');assert.equal(JSON.stringify(rulebook),snapshot);});
test('ledger balance and isolated margin are independent under real engine',()=>{const i=seed(),before=Risk.estimate(i).estimatedPriceUSD;i.events.push(fx.event(4,'capital_deposit',{amountUSD:'500',currency:'USD'}));assert.equal(Risk.estimate(i).estimatedPriceUSD,before);assert.equal(Core.reconstruct(i).capital.netContributedUSD,'2500');});
test('explicit margin transfer lowers model liquidation boundary under original V20 risk',()=>{const i=seed(),before=Risk.estimate(i).estimatedPriceUSD;i.events.push(fx.event(4,'margin_add',{amountUSD:'50',currency:'USD',purpose:'additional'}));const after=Risk.estimate(i).estimatedPriceUSD;assert.equal(before,'95000');assert.equal(after,'90000');});
test('floor inverse gives additional margin but never performs it',()=>{const x=Risk.inverse(seed(),{floorUSD:'80000'});assert.equal(x.additionalMarginUSD,'150');assert.equal(x.requiredTotalMarginUSD,'250');assert.equal(x.transferPerformed,false);assert.equal(x.protectionGuaranteed,false);});
test('late margin event after breaching maintenance does not rescue position',()=>{const i=seed(),at='2026-10-20T23:41:00Z',r=Risk.simulate(i,{steps:[{at,transition:'continuous',markPriceUSD:'94000',actions:[{outcome:'filled',events:[{...fx.event(4,'margin_add',{amountUSD:'200',currency:'USD',purpose:'additional'}),effective_at:at,recorded_at:at}]}]}]});assert.equal(r.firstFailure.reason,'MAINTENANCE_REACHED_BEFORE_ACTIONS');assert.equal(r.projectedLedger.cash.isolatedMarginUSD,'100');assert.equal(r.transfersPerformed,false);});
test('missed orders are not treated as executed',()=>{const i=fx.input(),a=Core.reconstruct(i);assert.equal(a.position.quantityBTC,'0');const c=Comparison.generate(input('v20-base-illustrative'));assert.equal(c.status,'comparison-only');assert.equal(Core.reconstruct(i).position.quantityBTC,'0');});
test('a PnL calculation must not be considered actual realised profit from preview',()=>{const v=run('v20-base-illustrative');assert.equal(v.mayWriteLedger,false);assert.equal(v.maySubmitOrders,false);assert.equal(v.status,'comparison-only');assert.equal(Object.hasOwn(v,'realizedPnLUSD'),false);});
test('order metadata quantization respects min size and never exceeds target allocation',()=>{for(const order of run('v20-base-illustrative').orders){assert.equal(order.metadataValid,true);assert.ok(Number(order.executableNominalUSD)<=Number(order.targetNominalUSD));assert.ok(Rules.validateOrder(rulebook,{priceUSD:order.entryPriceUSD,quantityBTC:order.quantityBTC,orderType:'limit'}).metadataValid);}});
test('without financial engine a read-only estimate is unavailable, not green',()=>{const x=Preview.run({request:input('v20-base-illustrative'),rules:rulebook,context:when});assert.equal(x.risk.status,'not-evaluated');assert.equal(x.risk.result,null);assert.equal(x.canApply,false);});
test('available wallet not transformed into collateral in simulated requirement',()=>{const a=input('v20-base-illustrative');a.walletCashUSD='500';const b={...a,walletCashUSD:'2500'};const x=Preview.run({request:a,rules:rulebook,context:when,riskEngine:Risk});const y=Preview.run({request:b,rules:rulebook,context:when,riskEngine:Risk});assert.equal(x.risk.result.requiredTotalMarginUSD,y.risk.result.requiredTotalMarginUSD);assert.equal(x.risk.officialLiquidation,false);});
test('actual reference rules 2026-10-20 have trading disabled',()=>{const x=Rules.load(rulebook);assert.equal(x.applicationPolicy.orderExecutionEnabled,false);assert.equal(x.applicationPolicy.transfersEnabled,false);assert.equal(x.applicationPolicy.specificRiskRecommendationsEnabled,false);});
